"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

    def set_next(self, node):
        self.next = node

class LinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.nodes = []
        print('Linked List Created\n')

    def __reserved_keyword__append(self, value):
        new_node = Node(value)
        print(f'Appended Value {value}')
        if (self.head is None):
            self.head = new_node
            self.tail = new_node
        else:
            self.tail.set_next(new_node)
            self.tail = new_node
        self.nodes.append(new_node)

    def prepend(self, value):
        print(f'Prepended Value {value} To The Front')
        new_node = Node(value)
        if (self.head is None):
            self.head = new_node
            self.tail = new_node
        else:
            new_node.set_next(self.head)
            self.head = new_node
        self.nodes.insert(0, new_node)

    def insert_at(self, index, value):
        print(f'Inserting Value {value} at Index {index}')
        if (index == 0):
            self.prepend(value)
            return
        new_node = Node(value)
        temp = self.head
        i = 0
        while ((temp is not None) and (i < (index - 1))):
            temp = temp.next
            i = (i + 1)
        if (temp is None):
            print('Insert Failed: Index out of range')
            return
        new_node.set_next(temp.next)
        temp.set_next(new_node)
        if (new_node.next is None):
            self.tail = new_node
        self.nodes.insert(index, new_node)
        print(f'Insert Successful: {value} Inserted at Index {index}')

    def create_cycle(self, start_index, end_index):
        print(f'\nCycle Created: Loop Start index {start_index} → End index  {end_index}')
        if ((start_index < 0) or (end_index < 0)):
            print('Cycle Creation Failed: Invalid Index')
            return
        if ((start_index >= len(self.nodes)) or (end_index >= len(self.nodes))):
            print('Cycle Creation Failed: Index Out Of Range')
            return
        start_node = self.nodes[start_index]
        end_node = self.nodes[end_index]
        end_node.set_next(start_node)
        print(f'\nCycle Created: Node {start_index} now points to node {end_index}')

    def remove_cycle(self):
        print('Remove Cycle Requested')
        slow = self.head
        fast = self.head
        cycle_found = False
        while (fast and fast.next):
            slow = slow.next
            fast = fast.next.next
            if (slow == fast):
                cycle_found = True
                print('Cycle Detected: Proceeding with Removal')
                break
        if (not cycle_found):
            print('No cycle found — nothing to remove')
            return
        slow = self.head
        while (slow != fast):
            slow = slow.next
            fast = fast.next
        cycle_start = slow
        temp = cycle_start
        while (temp.next != cycle_start):
            temp = temp.next
        temp.set_next(None)
        self.tail = self.nodes[(-1)]
        cycle_start_value = cycle_start.value
        print(f'Cycle Removed Successfully: Loop started at Node with Value {cycle_start_value}')

    def loop_diagram(self):
        print('\nGenerating Loop Diagram...\n')
        nodes = self.nodes
        visited = {}
        temp = self.head
        index = 0
        cycle_start = (-1)
        cycle_end = (-1)
        while (temp is not None):
            if (temp in visited):
                cycle_start = visited[temp]
                cycle_end = (index - 1)
                break
            visited[temp] = index
            temp = temp.next
            index = (index + 1)
        parts = []
        for node in nodes:
            parts.append(str(node.value))
        sep = ' → '
        chain = sep.join(parts)
        print(chain)
        if (cycle_start == (-1)):
            print('No Cycle Detected\n')
            return
        start_char = 0
        for i in range(cycle_start):
            start_char = (start_char + (len(parts[i]) + len(sep)))
        start_center = (start_char + (len(parts[cycle_start]) // 2))
        end_char = 0
        for i in range(cycle_end):
            end_char = (end_char + (len(parts[i]) + len(sep)))
        end_center = (end_char + (len(parts[cycle_end]) // 2))
        connector = ''
        i = 0
        while (i < start_center):
            connector = (connector + ' ')
            i = (i + 1)
        connector = (connector + '└')
        dash_count = ((end_center - start_center) - 1)
        i = 0
        while (i < dash_count):
            connector = (connector + '─')
            i = (i + 1)
        connector = (connector + '┘')
        print(connector)
        print(f'Cycle Detected From Node {cycle_start} to Node {cycle_end}\n')

setattr(LinkedList, '__reserved_keyword__append', LinkedList._LinkedList__reserved_keyword__append)

print('Detect Cycle in Singly Linked List\n')

l = LinkedList()

l.__reserved_keyword__append(10)

l.__reserved_keyword__append(20)

l.__reserved_keyword__append(30)

l.__reserved_keyword__append(40)

l.__reserved_keyword__append(50)

l.__reserved_keyword__append(60)

l.loop_diagram()

l.remove_cycle()

l.loop_diagram()

l.__reserved_keyword__append(40)

l.__reserved_keyword__append(50)

l.create_cycle(1, 6)

l.loop_diagram()

l.remove_cycle()

print('\nAfter Removing Cycle:')

l.loop_diagram()
